script.inlineScript:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const {label} = api.state.selectedFilterItem;
	return {
    "trigger": {
      "aria-label": helpers.translateSync("Selected filter: {0}", label)
    }
  };
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const status = { ...api.item.value.status };
	return status.value == 'complete' ? 'green' : 'warning';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync("Approval {0}", [api.item.value.status.displayValue.toLowerCase()]);
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const labelValue = api.item.value.request.displayValue + ": " + api.item.value.team_name.displayValue;
  return {
    "label": labelValue,
    "size":"sm"
  };
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
    return [{
        label: helpers.translateSync("Manager"),
        value: api.item.value.manager.displayValue
    }];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.item.value.members.members.slice(0,2);
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let shiftedMembers = [...api.item.value.members.members];
	shiftedMembers.shift();
	shiftedMembers.shift();
	return {
		propName: "popoverData",
		value: shiftedMembers
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({api, helpers}) {
    if (api.item.value.members.length < 3) {
        return "";
    }

    const count = api.item.value.members.members.length - 2;
    const teamName = api.item.value.team_name.displayValue;
    return {
        "button": {
            "aria-label": helpers.translateSync("Show {0} more members for team {1}", count, teamName)
        }
    };
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (api.item.value.members.length < 3)
    return "";

  var count = api.item.value.members.members.length - 2;
	return "+" + count.toString();
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
    const teamEmail = api.item.value.email.value;
    return [{
        label: helpers.translateSync("Email"),
        value: {
            type: "text-link",
            value: teamEmail,
            label: teamEmail,
            showIcon: false,
            href: "mailto:" + teamEmail,
            underlined: false,
            opensWindow: false
        }
    }];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const labelValue = api.item.value.request.displayValue + ": " + api.item.value.team_name.displayValue;
  return {
    "button": {
      "aria-label" : labelValue
    }
  };
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (!api.data.sow_team_management.canAddTeam) {
    return "";
  }

  return [{
    "label": helpers.translateSync("Add a team"),
    "tooltipContent": helpers.translateSync("Add or request a team"),
    "variant": "primary"
  }];
}

